import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a_str = input_data[1]
    b_str = input_data[2]

    a_digits = [int(c) for c in a_str]
    b_digits = [int(c) for c in b_str]

    diff = [a_digits[i] - b_digits[i] for i in range(n)]

    ops = []
    total_ops = 0

    for i in range(n - 1):
        if diff[i] == 0:
            continue

        d = diff[i]

        if d > 0:
            count = d
            if b_digits[i] + count > 9 or b_digits[i+1] - count < 0:
                if i == 0 and b_digits[0] + count == 1:
                    pass
                else:
                    print("-1")
                    return
            for _ in range(count):
                ops.append((i + 1, -1))
                total_ops += 1
                diff[i] -= 1
                diff[i+1] += 1
        else:
            count = -d
            if b_digits[i] - count < 0 or b_digits[i+1] + count > 9:
                if i == 0 and b_digits[0] - count == 1:
                    pass
                else:
                    print(-1)
                    return
            for _ in range(count):
                ops.append(i + 1, 1)
                total_ops += 1
                diff[i] += 1
                diff[i+1] -= 1

    if diff[-1] != 0:
        print("-1")
        return

    print(total_ops)
    limit = min(total_ops, 100000)
    for k in range(limit):
        d, s = ops[k]
        print(f"{d} {s}")

solve()
